insert into public.site_texts (id, data) values (1, '{"am":{"nav":{"about":"Մեր մասին","product":"Business Control","why":"Ինչու BC","industries":"Ոլորտներ","trust":"Վստահություն","contact":"Կապ","cta":"Պահանջել դեմո"},"hero":{"badge":"Բիզնեսի ավտոմատացման հարթակ","title":"Ավտոմատացրեք Ձեր բիզնես գործընթացները","subtitle":"LuysTech-ն օգնում է բիզնեսներին օպտիմալացնել գործառնությունները խելացի ավտոմատացման և Business Control (BC) հարթակի միջոցով։","ctaPrimary":"Պահանջել դեմո","ctaSecondary":"Կապվել մեզ հետ"},"about":{"kicker":"LuysTech-ի մասին","title":"Կառուցում ենք ավտոմատացված ձեռնարկությունը","lead":"Մենք ստեղծում ենք ձեռնարկությունների ավտոմատացման լուծումներ, որոնք պարզեցնում են բարդ գործընթացները և արագացնում թվային փոխակերպումը։","whoLabel":"Ովքե՞ր ենք մենք","whoText":"LuysTech-ը տեխնոլոգիական ընկերություն է՝ մասնագիտացած բիզնեսի ավտոմատացման և ձեռնարկությունների ծրագրային ապահովման ոլորտում։","whatLabel":"Ի՞նչ ենք անում","whatText":"Մենք մշակում ենք Business Control (BC) ERP համակարգը՝ վաճառք, գնումներ, պահեստ, առաքում և արտադրություն մեկ հարթակում, ՀԾ-ի և այլ ծառայությունների ինտեգրացիաներով։","missionLabel":"Մեր առաքելությունը","missionText":"Տրամադրել հուսալի գործիքներ, որոնք նվազեցնում են ձեռքով աշխատանքը և վերացնում սխալները։","visionLabel":"Մեր տեսլականը","visionText":"Դառնալ տարածաշրջանի բիզնեսների թվային փոխակերպման առաջատար գործընկերը։"},"bc":{"kicker":"Արտադրանք","title":"Business Control (BC)","desc":"Business Control-ը ERP համակարգ է վաճառքի, գնումների, պահեստի, առաքման և արտադրության համար՝ Django backend-ով և React ինտերֆեյսով։ Այն ինտեգրված է ՀԾ (ArmSoft) հաշվապահության, ScanIt-ի և հարկային էլ. հաշվառման հետ՝ ավտոմատացնելով փաստաթղթաշրջանառությունը մեկ միասնական համակարգում։"},"why":{"kicker":"Առավելություններ","title":"Ինչու՞ ընտրել Business Control"},"industries":{"kicker":"Ոլորտներ","title":"Ստեղծված յուրաքանչյուր ոլորտի համար"},"trust":{"clientsKicker":"Մեր հաճախորդները","clientsTitle":"Մեզ վստահում են","partnersKicker":"Ինտեգրացիաներ","partnersTitle":"Արտաքին համակարգերի ինտեգրացիա","successKicker":"Դեպքերի ուսումնասիրություն","successTitle":"Հաջողության պատմություններ","challenge":"Մարտահրավեր","solution":"Լուծում"},"demo":{"title":"Փոխակերպեք ձեր բիզնեսը այսօր","subtitle":"Բացահայտեք, թե ինչպես Business Control-ը կարող է ավտոմատացնել ձեր աշխատանքային հոսքերը։","ctaPrimary":"Պահանջել դեմո","ctaSecondary":"Կապվել մեզ հետ"},"contact":{"kicker":"Կապ","title":"Խոսենք ձեր բիզնեսի մասին","company":"Ընկերության անվանում","person":"Կոնտակտային անձ","phone":"Հեռախոս","email":"Էլ. փոստ","message":"Հաղորդագրություն","submit":"Ուղարկել հարցումը","success":"Շնորհակալություն։ Մենք շուտով կկապվենք ձեզ հետ։","phoneLabel":"Հեռախոս","emailLabel":"Էլ. փոստ","addressLabel":"Հասցե","hoursLabel":"Աշխատանքային ժամեր","mapText":"Քարտեզ"},"footer":{"desc":"Բիզնեսի ավտոմատացման լուծումներ Business Control հարթակի միջոցով։","quickTitle":"Արագ հղումներ","langTitle":"Լեզու","rights":"Բոլոր իրավունքները պաշտպանված են։"},"common":{"visit":"Այցելել կայք","viewStory":"Դիտել պատմությունը","watchVideo":"Դիտել վիդեոն","close":"Փակել","results":"Արդյունքներ"}},"en":{"nav":{"about":"About","product":"Business Control","why":"Why BC","industries":"Industries","trust":"Trust","contact":"Contact","cta":"Request Demo"},"hero":{"badge":"Business Automation Platform","title":"Automate Your Business Processes","subtitle":"LuysTech helps businesses optimize operations through intelligent automation and the Business Control (BC) platform.","ctaPrimary":"Request Demo","ctaSecondary":"Contact Us"},"about":{"kicker":"About LuysTech","title":"Engineering the automated enterprise","lead":"We build enterprise automation solutions that simplify complex operations and accelerate digital transformation.","whoLabel":"Who we are","whoText":"LuysTech is a technology company specializing in business automation and enterprise software.","whatLabel":"What we do","whatText":"We develop the Business Control (BC) ERP — sales, purchasing, storage, delivery and production in one platform, integrated with ArmSoft and other services.","missionLabel":"Our mission","missionText":"To deliver reliable tools that reduce manual work and eliminate operational errors.","visionLabel":"Our vision","visionText":"To become the leading digital transformation partner for businesses across the region."},"bc":{"kicker":"Product","title":"Business Control (BC)","desc":"Business Control is an ERP for sales, purchasing, storage, delivery and production, with a Django backend and a React interface. It integrates with the ArmSoft accounting system, ScanIt and tax e-invoicing, automating document flow in one unified system."},"why":{"kicker":"Benefits","title":"Why choose Business Control"},"industries":{"kicker":"Industries","title":"Built for every industry"},"trust":{"clientsKicker":"Our Clients","clientsTitle":"Trusted by Leading Businesses","partnersKicker":"Integrations","partnersTitle":"External system integrations","successKicker":"Case Studies","successTitle":"Success Stories","challenge":"Challenge","solution":"Solution"},"demo":{"title":"Transform Your Business Operations Today","subtitle":"Discover how Business Control can automate and optimize your workflows.","ctaPrimary":"Request Demo","ctaSecondary":"Contact Us"},"contact":{"kicker":"Contact","title":"Let''s talk about your business","company":"Company Name","person":"Contact Person","phone":"Phone Number","email":"Email","message":"Message","submit":"Send Request","success":"Thank you! We will get back to you shortly.","phoneLabel":"Phone","emailLabel":"Email","addressLabel":"Address","hoursLabel":"Working Hours","mapText":"Map placeholder"},"footer":{"desc":"Business automation solutions powered by the Business Control platform.","quickTitle":"Quick Links","langTitle":"Language","rights":"All rights reserved."},"common":{"visit":"Visit website","viewStory":"View story","watchVideo":"Watch video","close":"Close","results":"Results"}},"ru":{"nav":{"about":"О нас","product":"Business Control","why":"Почему BC","industries":"Отрасли","trust":"Доверие","contact":"Контакты","cta":"Запросить демо"},"hero":{"badge":"Платформа бизнес-автоматизации","title":"Автоматизируйте бизнес-процессы","subtitle":"LuysTech помогает компаниям оптимизировать операции с помощью интеллектуальной автоматизации и платформы Business Control (BC).","ctaPrimary":"Запросить демо","ctaSecondary":"Связаться с нами"},"about":{"kicker":"О LuysTech","title":"Создаём автоматизированное предприятие","lead":"Мы создаём решения для автоматизации предприятий, которые упрощают сложные процессы и ускоряют цифровую трансформацию.","whoLabel":"Кто мы","whoText":"LuysTech — технологическая компания, специализирующаяся на бизнес-автоматизации и корпоративном ПО.","whatLabel":"Что мы делаем","whatText":"Мы разрабатываем ERP Business Control (BC) — продажи, закупки, склад, доставку и производство на одной платформе, с интеграцией ArmSoft и других сервисов.","missionLabel":"Наша миссия","missionText":"Предоставлять надёжные инструменты, сокращающие ручной труд и устраняющие ошибки.","visionLabel":"Наше видение","visionText":"Стать ведущим партнёром по цифровой трансформации для бизнеса в регионе."},"bc":{"kicker":"Продукт","title":"Business Control (BC)","desc":"Business Control — ERP для продаж, закупок, склада, доставки и производства, с Django-бэкендом и React-интерфейсом. Интегрируется с бухгалтерией ArmSoft, ScanIt и налоговым э-инвойсингом, автоматизируя документооборот в единой системе."},"why":{"kicker":"Преимущества","title":"Почему стоит выбрать Business Control"},"industries":{"kicker":"Отрасли","title":"Создано для каждой отрасли"},"trust":{"clientsKicker":"Наши клиенты","clientsTitle":"Нам доверяют","partnersKicker":"Интеграции","partnersTitle":"Интеграции с внешними системами","successKicker":"Кейсы","successTitle":"Истории успеха","challenge":"Задача","solution":"Решение"},"demo":{"title":"Преобразите бизнес-операции уже сегодня","subtitle":"Узнайте, как Business Control автоматизирует и оптимизирует ваши процессы.","ctaPrimary":"Запросить демо","ctaSecondary":"Связаться с нами"},"contact":{"kicker":"Контакты","title":"Поговорим о вашем бизнесе","company":"Название компании","person":"Контактное лицо","phone":"Телефон","email":"Эл. почта","message":"Сообщение","submit":"Отправить запрос","success":"Спасибо! Мы скоро свяжемся с вами.","phoneLabel":"Телефон","emailLabel":"Эл. почта","addressLabel":"Адрес","hoursLabel":"Часы работы","mapText":"Карта"},"footer":{"desc":"Решения для автоматизации бизнеса на базе платформы Business Control.","quickTitle":"Быстрые ссылки","langTitle":"Язык","rights":"Все права защищены."},"common":{"visit":"Перейти на сайт","viewStory":"Смотреть историю","watchVideo":"Смотреть видео","close":"Закрыть","results":"Результаты"}}}'::jsonb)
