insert into public.modules (id,key,icon,image_url,image_url_light,title,"desc",sort,active) values ('sales','sales','trend',null,null,'{"am":"Վաճառք","en":"Sales","ru":"Продажи"}'::jsonb,'{"am":"Վաճառքի ողջ ցիկլը՝ պատվերից մինչև բեռնագիր, ամրագրում, վերադարձ և վճարումներ։","en":"The full sales cycle — from order to waybill, reservation, return and payments.","ru":"Полный цикл продаж — от заказа до накладной, резервирования, возврата и оплат."}'::jsonb,1,true) on conflict (id) do nothing;
